method max_fill(grid: array<array<int>>, capacity: int) returns (result: int)
    requires 1 <= capacity <= 10
    requires 1 <= grid.Length <= 100
    requires forall i :: 0 <= i < grid.Length ==> (1 <= grid[i].Length <= 100)
    requires forall i, j :: 0 <= i < grid.Length && 0 <= j < grid[i].Length ==> (grid[i][j] == 0 || grid[i][j] == 1)
    ensures result >= 0
    ensures result == sum(i: int | 0 <= i < grid.Length | count_water(grid[i]) / capacity)

    // Helper function to count the number of water units in a row
    function count_water(row: array<int>): int
        requires row.Length > 0
        ensures 0 <= count_water(row) <= row.Length
    {
        var count := 0;
        var i := 0;
        while i < row.Length
            invariant 0 <= i <= row.Length
            invariant count == Count(j: int | 0 <= j < i && row[j] == 1)
        {
            if row[i] == 1 {
                count := count + 1;
            }
            i := i + 1;
        }
        return count;
    }
